// tests/system/session_lock_test.cc — house pattern (bootOutput/pumpUntil/lockNow) from lock_interactions_test.cc.
TEST_CASE("unlock re-focuses an ABA-recycled impostor via the stale focus_before_lock_ handle") {
    setenv("WLR_BACKENDS", "headless", 1); setenv("WLR_RENDERER", "pixman", 1);
    Server server(true); REQUIRE(server.ok()); bootOutput(server);

    // 1-2. Map + focus View A; record its heap address.
    test::TestClient appA(server.socketName(), 0xFFFF0000u, 200, 150); REQUIRE(appA.ok());
    REQUIRE(pumpUntil(server, [&]{auto&v=server.viewsForTest(); return !v.empty()&&v[0]->isMapped();},
                      [&]{appA.flush();appA.pump();}));
    server.focusViewForTest(server.viewsForTest()[0].get());
    void *addrA = server.viewsForTest()[0].get();
    REQUIRE(server.focusedViewForTest() == addrA);

    // 3. Lock (fallback path) -> handleSessionLocked stashes focus_before_lock_ = A.
    test::LockTestClient lc(server.socketName()); REQUIRE(lc.ok());
    lockNow(server, lc, [&]{appA.flush();appA.pump();lc.flush();lc.pump();});
    REQUIRE(server.focusedViewForTest() == nullptr);

    // 4. Client destroys A's toplevel while locked -> removeView frees it; handle NOT scrubbed.
    appA.destroyOne(test::TestClient::Obj::Toplevel);
    REQUIRE(pumpUntil(server, [&]{return server.viewsForTest().empty();},
                      [&]{appA.flush();appA.pump();lc.flush();lc.pump();}));

    // 5. New client creates a toplevel under the lock but never commits a buffer (unmapped impostor).
    test::TestClient appB(server.socketName(), 0xFF00FF00u, 200, 150); // ctor sends surface+get_toplevel
    REQUIRE(pumpUntil(server, [&]{return server.viewsForTest().size()==1;},
                      [&]{appB.flush();appB.pump();lc.flush();lc.pump();}));
    void *addrB = server.viewsForTest()[0].get();
    // The load-bearing ABA: single free-then-alloc of a same-size View -> tcache LIFO reuse.
    // This is probabilistic; capture it so a miss reports "not reproduced" rather than a false green.
    CAPTURE(addrA); CAPTURE(addrB);
    REQUIRE(addrB == addrA);                 // if this fails, ASLR/tcache did not reuse — rerun
    REQUIRE_FALSE(server.viewsForTest()[0]->isMapped());

    // 6. Unlock -> handleSessionUnlocked. BUG: viewForHandle matches the impostor by address.
    lc.unlockAndDestroy();
    REQUIRE(pumpUntil(server, [&]{return !server.sessionLockForTest()->locked();},
                      [&]{appB.flush();appB.pump();lc.flush();lc.pump();}));
    // Correct behavior: no mapped view -> fallback clears focus. Buggy: impostor gets focus.
    CHECK(server.focusedViewForTest() == nullptr);   // FAILS today: equals the unmapped impostor
    // (If wlroots 0.20 asserts base->initialized inside set_activated, step 6 aborts instead.)
}
