// tests/system/hostile_client_test.cc house pattern (HeadlessFixture + TestClient).
// One-line harness addition needed: TestClient::hideKeepingRole() does
//   wl_surface_attach(impl->surface, nullptr, 0, 0); wl_surface_commit(impl->surface);
//   wl_display_flush(impl->display);
// (commitBareSurface() will NOT work: it commits with no new attach, so
//  WLR_SURFACE_STATE_BUFFER is unset and the surface never unmaps.)

TEST_CASE("focused client hides via NULL-buffer commit, next focus asserts") {
  setenv("WLR_BACKENDS", "headless", 1);
  setenv("WLR_RENDERER", "pixman", 1);
  Server server(/*headless=*/true);          // defaults: focusNewWindows=true, SloppyFocus
  boot(server);

  // Client A maps and takes focus.
  auto a = makeMapped(server);               // focused_view == View A
  REQUIRE(server.viewsForTest().size() == 1);

  // A hides the xdg way: attach(NULL)+commit. Role kept, initialized=false,
  // View A survives, focused_view still == A (no unmap hook scrubs it).
  a->hideKeepingRole();
  for (int i = 0; i < 40; ++i) { a->flush(); server.dispatch(); a->pump(); }
  REQUIRE(server.viewsForTest().size() == 1);        // View A not destroyed
  CHECK_FALSE(server.viewsForTest().back()->isMapped());

  // Trigger the next focus transition. EITHER:
  //  (variant 1) a second client maps -> focusNewWindows -> focusView(B) ->
  //              set_activated(A,false) at Server.cc:898 on the reset surface.
  auto b = makeMapped(server);   // EXPECTED (pre-fix): SIGABRT via assert(surface->initialized)

  //  (variant 2, single client) swap the makeMapped(b) above for a workspace
  //  switch onto an empty workspace, which routes through clearFocus():
  //     server.injectKeyForTest(XKB_KEY_Right, WLR_MODIFIER_LOGO, true);
  //     server.injectKeyForTest(XKB_KEY_Right, WLR_MODIFIER_LOGO, false);
  //     for (int i=0;i<20;++i) server.dispatch();   // clearFocus -> Server.cc:1728 -> assert

  // Post-fix expectation (onViewUnmapped parks focus + mapped/initialized gate
  // before every wlr_xdg_toplevel_set_*): no abort; server keeps compositing.
  for (int i = 0; i < 10; ++i) server.dispatch();
  test::Frame f = test::captureFrame(server);
  CHECK(f.w == 1280u);
}

// Prereq: one tiny TestClient addition in the style of destroyToplevelKeepSurface
