// Leave impl->buffer untouched: surf_configure (TestClient.cc:93) only re-attaches when
// !buffer || size changed, so later configures are ack-only and cannot remap behind the test.

TEST_CASE("bindings on a stale unmapped focused_view: snap/fullscreen must not assert-abort") {
  setenv("WLR_BACKENDS", "headless", 1);
  setenv("WLR_RENDERER", "pixman", 1);
  Server server(/*headless=*/true);
  boot(server);                                    // house helper, hostile_client_test.cc:53

  auto c = makeMapped(server);                     // maps + auto-focuses (focusNewWindows), view at (300,200)
  REQUIRE(server.viewsForTest().back()->isMapped());

  c->unmapKeepRole();                              // NULL-buffer commit: unmap, xdg role stays alive
  REQUIRE(pumpUntil(server, *c,
      [&] { return !server.viewsForTest().empty()
                 && !server.viewsForTest().back()->isMapped(); }));
  // focused_view still points at the now surface->initialized==false view.

  // Pre-fix each of these SIGABRTs synchronously inside wlr_xdg_surface_schedule_configure
  // (assert(surface->initialized)); run under ASAN/plain build, the abort IS the failure.
  server.injectKeyForTest(XKB_KEY_Left, WLR_MODIFIER_LOGO | WLR_MODIFIER_SHIFT, true);  // SnapLeft -> resizeTo/set_tiled
  server.injectKeyForTest(XKB_KEY_Left, WLR_MODIFIER_LOGO | WLR_MODIFIER_SHIFT, false);
  server.injectKeyForTest(XKB_KEY_f, WLR_MODIFIER_LOGO, true);                          // ToggleFullscreen -> set_fullscreen
  server.injectKeyForTest(XKB_KEY_f, WLR_MODIFIER_LOGO, false);

  // House alive-contract (runScript pattern): still dispatching + compositing, client unharmed.
  for (int i = 0; i < 10; ++i) server.dispatch();
  test::Frame f = test::captureFrame(server);
  CHECK(f.w == 1280u);
  CHECK(f.h == 720u);
  CHECK(!c->errored());                            // legal client must never be zapped
}

