//  fires removeView which prunes cycle_start_ and masks the bug; the iconify seam
//  doesn't reset wlroots' `initialized` flag so set_activated wouldn't abort.)

TEST_CASE("Escape mid-cycle after the start window unmapped must not abort") {
  setenv("WLR_BACKENDS", "headless", 1);
  setenv("WLR_RENDERER", "pixman", 1);
  Server server(/*headless=*/true);
  REQUIRE(server.ok());
  for (int i = 0; i < 50 && server.activeSceneOutputForTest() == nullptr; ++i)
    server.dispatch();

  // B first, then A, so A is topmost and the titlebar click focuses A. MRU: A,B.
  test::TestClient b(server.socketName(), 0xFF00FF00u, 200, 150);
  test::TestClient a(server.socketName(), 0xFFFF0000u, 200, 150);
  REQUIRE(a.ok()); REQUIRE(b.ok());
  for (int i = 0; i < 1200 && server.viewsForTest().size() < 2; ++i) {
    a.flush(); b.flush(); server.dispatch(); a.pump(); b.pump();
  }
  for (int i = 0; i < 60; ++i) { a.flush(); b.flush(); server.dispatch(); a.pump(); b.pump(); }
  REQUIRE(server.viewsForTest().size() == 2);
  for (auto &up : server.viewsForTest()) up->setPosition(160, 120);
  View *vb = server.viewsForTest()[0].get();
  View *va = server.viewsForTest()[1].get();
  server.injectPointerMotionForTest(260, 130);
  server.injectPointerButtonForTest(BTN_LEFT, true);
  server.injectPointerButtonForTest(BTN_LEFT, false);
  REQUIRE(server.focusedViewForTest() == va);          // cycle_start_ will be A

  // Alt held: Alt+Tab through the real binding funnel -> preview B.
  server.injectKeyForTest(XKB_KEY_Tab, WLR_MODIFIER_ALT, /*pressed=*/true);
  REQUIRE(server.cyclingForTest());
  REQUIRE(server.focusedViewForTest() == vb);

  // A unmaps while the modifier is held: NULL-buffer commit, role kept.
  // removeView never runs, so cycle_start_ still points at A; wlroots has
  // reset A's xdg_surface (initialized=false) but the toplevel is alive.
  a.unmapKeepToplevel();
  for (int i = 0; i < 200 && va->isMapped(); ++i) {
    a.flush(); b.flush(); server.dispatch(); a.pump(); b.pump();
  }
  REQUIRE_FALSE(va->isMapped());
  REQUIRE(server.cyclingForTest());

  // Escape -> cancelCycle -> focusView(A) -> set_activated on the reset
  // surface -> assert(surface->initialized) -> abort. Pre-fix this line kills
  // the test binary; post-fix the cancel must skip (or safely handle) the
  // unmapped start window.
  server.injectKeyForTest(XKB_KEY_Escape, WLR_MODIFIER_ALT, true);
  CHECK_FALSE(server.cyclingForTest());
  CHECK(server.focusedViewForTest() != va);            // nothing sane to restore onto
}

