// In tests/system/icon_menu_test.cc (reuses its itemY/pumpUntilBothMapped/clickIconifyButton helpers)
TEST_CASE("icon menu deiconify of a client-unmapped icon must not abort") {
  setenv("WLR_BACKENDS", "headless", 1);
  setenv("WLR_RENDERER", "pixman", 1);
  Server server(/*headless=*/true);
  REQUIRE(server.ok());
  for (int i = 0; i < 50 && server.activeSceneOutputForTest() == nullptr; ++i) server.dispatch();

  test::TestClient ca(server.socketName(), 0xFFFF0000u, 200, 150, test::TestClient::Deco::RequestSSD);
  test::TestClient cb(server.socketName(), 0xFF00FF00u, 200, 150, test::TestClient::Deco::RequestSSD);
  REQUIRE(ca.ok()); REQUIRE(cb.ok());
  pumpUntilBothMapped(server, ca, cb);
  View *A = server.viewsForTest()[0].get();
  server.viewsForTest()[1]->setPosition(160, 400);

  // Focus A, then iconify via its titlebar button (F4.3 path) -> icons_ holds A.
  server.injectPointerMotionForTest(260, 130);
  server.injectPointerButtonForTest(BTN_LEFT, true);
  server.injectPointerButtonForTest(BTN_LEFT, false);
  REQUIRE(server.focusedViewForTest() == A);
  clickIconifyButton(server, A);
  REQUIRE(A->isIconified());

  // Client withdraws the hidden window: NULL-buffer commit, role objects kept.
  ca.unmapKeepRole();
  for (int i = 0; i < 30; ++i) { ca.flush(); cb.flush(); server.dispatch(); ca.pump(); cb.pump(); }
  REQUIRE_FALSE(A->isMapped());          // unmapped, xdg surface reset, still in icons_

  // Icon menu still lists the stale icon; click its row.
  const int menu_x = 800, menu_y = 400;
  server.injectPointerMotionForTest(menu_x, menu_y);
  server.injectPointerButtonForTest(BTN_MIDDLE, true);
  REQUIRE(server.menuOpenForTest());
  REQUIRE(server.rootMenuForTest()->itemCount() == 1);
  const int iy = itemY(menu_y, menu::titleHeight(18), 0);
  server.injectPointerMotionForTest(menu_x + 30, iy);
  server.injectPointerButtonForTest(BTN_LEFT, true);
  // PRE-FIX: SIGABRT here - deiconifyView -> focusView -> wlr_xdg_toplevel_set_activated
  // -> assert(surface->initialized), wlr_xdg_surface.c:168 (wlroots 0.20.1).
  server.injectPointerButtonForTest(BTN_LEFT, false);

  // POST-FIX contract: menu dismissed, server alive and compositing.
  CHECK_FALSE(server.menuOpenForTest());
  for (int i = 0; i < 10; ++i) server.dispatch();
  test::Frame f = test::captureFrame(server);
  CHECK(f.w == 1280u);
  CHECK(f.h == 720u);
}

