  setenv("WLR_BACKENDS", "headless", 1);
  setenv("WLR_RENDERER", "pixman", 1);
  Server server(/*headless=*/true);
  boot(server);
  test::TestClient c(server.socketName(), 0xFF33CC66u, 200, 150,
                     test::TestClient::Deco::RequestSSD);
  REQUIRE(c.ok());
  View *v = mapOne(server, c);            // maps: xdg_toplevel->base->initialized == true
  v->setPosition(250, 180);

  Menu *m = openWindowMenu(server, v);    // right-click titlebar -> modal window menu; rows target v
  REQUIRE(server.menuOpenForTest());

