  REQUIRE_FALSE(v->isMapped());                       // unmap took effect
  REQUIRE(server.viewForHandleForTest(v) == v);       // View still alive (removeView not called)
  REQUIRE(server.menuOpenForTest());                  // unmap did NOT close the menu

  // Click "Maximize" (row idx 3). Pre-fix: viewForHandle(v) resolves the unmapped
  // view -> setMaximized -> wlr_xdg_toplevel_set_maximized -> schedule_configure
  // -> assert(initialized) -> abort. Post-fix: the menu path must guard on
  // initialized/mapped and no-op instead of aborting.
  clickRow(server, m, 3);                             // BTN_LEFT press on the Maximize row

  CHECK_FALSE(server.menuOpenForTest());              // menu closed
  for (int i = 0; i < 10; ++i) server.dispatch();     // server still alive & dispatching
  test::Frame f = test::captureFrame(server);
  CHECK(f.w == 1280u);
}
