// Extends tests/system/session_lock_test.cc — reuses bootOutput/pumpUntil and
// the same seams as "takeover keeps the pre-lock focus for the eventual unlock".
TEST_CASE("ABA: a View freed under the lock leaves focus_before_lock_ dangling; "
          "a recycled address hijacks the unlock focus restore") {
    setenv("WLR_BACKENDS", "headless", 1);
    setenv("WLR_RENDERER", "pixman", 1);
    Server server(/*headless=*/true);
    REQUIRE(server.ok());
    bootOutput(server);

    // 1. A mapped + focused before the lock.
    auto a = std::make_unique<test::TestClient>(server.socketName(), 0xFFFF0000u, 200, 150);
    REQUIRE(a->ok());
    auto aMapped = [&]{ const auto &v = server.viewsForTest();
                        return !v.empty() && v[0]->isMapped(); };
    REQUIRE(pumpUntil(server, aMapped, [&]{ a->flush(); a->pump(); }));
    server.viewsForTest()[0]->setPosition(160,120);
    server.injectPointerMotionForTest(260,130);
    server.injectPointerButtonForTest(BTN_LEFT, true);
    server.injectPointerButtonForTest(BTN_LEFT, false);
    View *va = server.viewsForTest()[0].get();
    REQUIRE(server.focusedViewForTest() == va);
    const void *freed_addr = static_cast<const void*>(va);   // capture A's address

    // 2. Lock -> handleSessionLocked stamps focus_before_lock_ = va.
    test::LockTestClient lc(server.socketName());
    REQUIRE(lc.ok());
    REQUIRE(pumpUntil(server, [&]{ return lc.sawLockManager(); },
                      [&]{ lc.flush(); lc.pump(); }));
    lc.lock();
    REQUIRE(pumpUntil(server, [&]{ return server.sessionLockForTest()->locked(); },
                      [&]{ lc.flush(); lc.pump(); }));
    server.advanceClockForTest(2);
    REQUIRE(pumpUntil(server, [&]{ return lc.lockedReceived(); },
                      [&]{ lc.flush(); lc.pump(); }));

    // 3. Under the lock, A dies. removeView frees View A but never scrubs
    //    focus_before_lock_ (grep: only set/read/clear, never in removeView).
    a->closeWindow();                    // xdg_toplevel destroy -> removeView(A) -> free
    REQUIRE(pumpUntil(server, [&]{ return server.viewsForTest().empty(); },
                      [&]{ a->flush(); a->pump(); lc.flush(); lc.pump(); }));

    // 4. Under the lock, a new client maps. make_unique<View> is ungated;
    //    same-size-class reuse is likely to hand back A's freed chunk.
    auto c = std::make_unique<test::TestClient>(server.socketName(), 0xFF00FF00u, 200, 150);
    REQUIRE(c->ok());
    REQUIRE(pumpUntil(server, [&]{ const auto &v = server.viewsForTest();
                                   return v.size()==1 && v[0]->isMapped(); },
                      [&]{ c->flush(); c->pump(); lc.flush(); lc.pump(); }));
    View *vc = server.viewsForTest()[0].get();
    REQUIRE(server.focusedViewForTest() == nullptr);          // focusView is lock-gated

    // 5. Unlock. viewForHandle does a bare pointer scan.
    lc.unlockAndDestroy();
    REQUIRE(pumpUntil(server, [&]{ return !server.sessionLockForTest()->locked(); },
                      [&]{ c->flush(); c->pump(); lc.flush(); lc.pump(); }));

    // The ABA fires exactly when the allocator recycled A's address into C.
    if (static_cast<const void*>(vc) == freed_addr) {
        // BUG (pre-fix): stale handle matches the unrelated C -> wrong focus.
        CHECK(server.focusedViewForTest() == vc);            // demonstrates the hijack
        // Post-fix (scrub focus_before_lock_ in removeView) this becomes the
        // intended topmost/clear fallback, so vc would NOT be the match.
    } else {
        WARN("allocator did not recycle A's address this run; ABA window not hit");
    }
}

// tests/system/hostile_client_test.cc house pattern; NOTE: decoration_test.cc:90
// ("destroying only the decoration object leaves the View intact") ALREADY drives
// this exact path — CHECK(v->decorationMode() == -1) at line 109 passes only if
// the UB statement View.cc:198 executed. A dedicated sketch:
TEST_CASE("hostile: decoration-only destroy runs the self-disconnected deco_destroy_ closure") {
  setenv("WLR_BACKENDS", "headless", 1);
  setenv("WLR_RENDERER", "pixman", 1);
  Server server(/*headless=*/true);
  boot(server);  // pump until activeSceneOutputForTest()
  test::TestClient c(server.socketName(), 0xFF00FF00u, 200, 150,
                     test::TestClient::Deco::RequestSSD);   // binds deco_destroy_ via attachDecoration
  REQUIRE(c.ok());
  REQUIRE(pumpUntil(server, c, [&] { return mapped(server); }));
  const View *v = server.viewsForTest().back().get();
  REQUIRE(v->decorationMode() == kModeServerSide);          // decoration attached, listeners live
  c.destroyOne(test::TestClient::Obj::Decoration);          // legal: decoration dies, toplevel kept
  for (int i = 0; i < 60; ++i) { c.flush(); server.dispatch(); c.pump(); }
  // ^ server.dispatch() here runs View.cc:196-198: line 197 destroys the executing
  //   closure, line 198 reads its captured `this` out-of-lifetime. Benign bytes today.
  REQUIRE_FALSE(server.viewsForTest().empty());
  CHECK(v->decorationMode() == -1);   // proves line 198's scrub ran, i.e. the UB read happened
  CHECK(v->drawsFrame());             // policy: keep SSD after channel loss
  CHECK(v->isMapped());
  // Server demonstrably alive (house pattern):
  test::Frame f = test::captureFrame(server);
  CHECK(f.w == 1280u);
  // Caveat: this test cannot FAIL on the UB itself — the read is of intact SBO
  // bytes inside the still-alive Listener member; ASAN/UBSAN do not detect it.
  // It pins reachability + survival; the fix (scrub `decoration` and disconnect
  // deco_request_mode_ first, self-disconnect LAST) keeps it green.
}

// Add to tests/system/windowmenu_test.cc (helpers boot/mapOne/openWindowMenu/clickRow already exist there).
// Demonstrates the ABA: the Windowmenu's baked target survives View A's death and
// is re-matched to a recycled View B, so Close hits the wrong window.
TEST_CASE("Windowmenu target is defeated by heap reuse (ABA)") {
  setenv("WLR_BACKENDS", "headless", 1);
  setenv("WLR_RENDERER", "pixman", 1);
  Server server(/*headless=*/true);
  boot(server);

  // 1. Map A, right-click its titlebar -> menu bakes target = (void*)&A.
  auto a = std::make_unique<test::TestClient>(server.socketName(), 0xFF3366CCu, 200,150,
                                              test::TestClient::Deco::RequestSSD);
  REQUIRE(a->ok());
  View *A = mapOne(server, *a);
  void *bakedP = A;                          // == A->windowID()
  A->setPosition(300, 200);
  Menu *m = openWindowMenu(server, A);       // active_menu_ holds target==bakedP
  REQUIRE(server.menuOpenForTest());

  // 2. Client A destroys its toplevel; View A is freed. removeView never closes
  //    the menu nor scrubs the baked target.
  a->destroyOne(test::TestClient::Obj::Toplevel);
  for (int i=0;i<200;i++){ a->flush(); server.dispatch(); a->pump(); }
  REQUIRE(server.menuOpenForTest());         // menu still open, target dangling

  // 3. Map B; retry until tcache hands back A's exact address (usually first try).
  std::unique_ptr<test::TestClient> b;
  View *B = nullptr;
  for (int attempt=0; attempt<8 && B==nullptr; ++attempt) {
    auto cand = std::make_unique<test::TestClient>(server.socketName(), 0xFF33CC66u,200,150,
                                                   test::TestClient::Deco::RequestSSD);
    REQUIRE(cand->ok());
    View *v = mapOne(server, *cand);
    if (v == static_cast<View*>(bakedP)) { b = std::move(cand); B = v; }
    else cand->closeWindow();               // wrong slot, free and retry
  }
  REQUIRE(B != nullptr);                     // View B reused A's address == bakedP

  // 4. Click 'Close' (row 5) in the still-open stale menu.
  clickRow(server, m, 5);
  CHECK_FALSE(server.menuOpenForTest());
  // BUG: the close request lands on B, the innocent window.
  bool bClosed=false;
  for (int i=0;i<200 && !bClosed;i++){ b->flush(); server.dispatch(); b->pump();
                                       bClosed = b->gotCloseRequest(); }
  CHECK(bClosed);                            // wrong window asked to close (demonstrates the defect)
  // A correct compositor would have closed the menu when A died -> no close to anyone.
}

// tests/system/session_lock_test.cc pattern; run under build-asan and,
// crucially, also at -O1/-O2 (the -O0 build hides the read in a register).
// This is the in-tree :379 test tightened to pin the UB window: head 0 never
// commits, so `locked` can ONLY arrive via the post-erase recount at
// SessionLock.cc:91 - i.e. the freed-closure read is on the asserted path.
TEST_CASE("hot-unplug while locked: destroy handler must not read captures after erasing its own PerOutput") {
    setenv("WLR_BACKENDS", "headless", 1);
    setenv("WLR_RENDERER", "pixman", 1);
    Server server(/*headless=*/true);
    REQUIRE(server.ok());
    bootOutput(server);
    server.addHeadlessOutputForTest(800, 600);
    REQUIRE(pumpUntil(server, [&] { return server.outputCountForTest() == 2; }, [&] {}));

    test::LockTestClient lc(server.socketName());
    REQUIRE(lc.ok());
    REQUIRE(pumpUntil(server, [&] { return lc.sawLockManager(); },
                      [&] { lc.flush(); lc.pump(); }));
    lc.lock();
    // Zero-sleep pumps: lock lands, both heads blanked, no post-blank commit
    // yet -> locked_sent_ is false and BOTH PerOutput entries are live.
    REQUIRE(pumpUntil(server, [&] {
        return server.sessionLockForTest()->locked()
            && server.sessionLockForTest()->blankRectCountForTest() == 2;
    }, [&] { lc.flush(); lc.pump(); }));
    REQUIRE_FALSE(server.sessionLockForTest()->lockedSentForTest());

    // Hot-unplug head 1 mid-wait. Inside this call the output_destroy handler
    // erase_if-frees its own PerOutput (closure storage) then calls
    // maybeSendLocked() off the freed capture (SessionLock.cc:88->91).
    // ASAN on an optimized build reports heap-use-after-free HERE.
    server.destroyOutputForTest(1);
    CHECK(server.sessionLockForTest()->blankRectCountForTest() == 1);

    // The recount is load-bearing: head 0 never commits a post-blank frame in
    // zero-sleep pumps, so `locked` arriving proves maybeSendLocked ran after
    // the erase - the fixed code must keep the recount, off a stack ref
    // (SessionLock &self = *this; taken before the erase).
    CHECK(pumpUntil(server, [&] { return lc.lockedReceived(); },
                    [&] { lc.flush(); lc.pump(); }, /*iters=*/3000, /*sleep_us=*/1000));
    CHECK(server.sessionLockForTest()->lockedSentForTest());
    lc.unlockAndDestroy();
    REQUIRE(pumpUntil(server, [&] { return !server.sessionLockForTest()->locked(); },
                      [&] { lc.flush(); lc.pump(); }));
}

