  pid_t busDaemonPid() {   // same helper as sni_host_test.cc:614-626
    sd_bus *probe = nullptr;
    REQUIRE(sd_bus_open_user(&probe) >= 0);
    sd_bus_message *reply = nullptr; uint32_t pid = 0;
