  REQUIRE_FALSE(it.menu_path.empty());

  const pid_t daemon = busDaemonPid();
  REQUIRE(daemon > 0);
  kill(daemon, SIGKILL);           // session bus dies; Host hasn't drained yet
  usleep(50 * 1000);               // kernel closes the daemon's sockets

  // Case A window: the right-click lands before the Host's fd source dispatches
