  // Pump hard: drain feeds the synthetic Disconnected reply to onAboutToShow,
  // fetchLayout's resend fails silently (-ENOTCONN ignored), Host tears its
  // bus down. Nothing will ever invoke on_layout_ after this.
  for (int i = 0; i < 300; ++i) { server.dispatch(); usleep(2000); }

  CHECK_FALSE(server.sniHostForTest()->ok());     // Host went inert, as designed
  CHECK_FALSE(server.menuOpenForTest());          // no stale menu appeared
  CHECK_FALSE(server.sniMenuInFlightForTest());   // FAILS TODAY: wedged non-null forever

  // The user-visible lockup: every opener refuses and no input recovers.
