  CHECK(server.menuOpenForTest());                // FAILS TODAY (Server.cc:2011 gate)
  server.injectKeyForTest(XKB_KEY_Escape, 0, true);   // no-op: gated on active_menu_
  server.openIconMenu(100, 100);
  CHECK(server.menuOpenForTest());                // FAILS TODAY (Server.cc:2160 gate)
  mock.quit();
}

