// tests/system/clipboard_shutdown_leak_test.cc — house pattern of
// clipboard_image_test.cc + screenshot_e2e_test.cc:79-83 (impl->send IS the
// server-side landing point of a real client's wl_data_offer.receive).
TEST_CASE("in-flight paste Writer is reclaimed at compositor shutdown") {
  setenv("WLR_BACKENDS", "headless", 1);
  setenv("WLR_RENDERER", "pixman", 1);
  int rfd = -1, wfd = -1;
  ClipboardImage::Blob blob;                 // test-held ref = leak probe
  {
    Server server(/*headless=*/true);
    REQUIRE(server.ok());
    for (int i = 0; i < 50 && server.activeSceneOutputForTest() == nullptr; ++i) server.dispatch();

    // Incompressible pixels -> PNG > 64 KiB pipe buffer, so the writer parks
    // on WL_EVENT_WRITABLE exactly like a stalled real paster.
    std::vector<uint32_t> px(256 * 256);
    uint32_t s = 1; for (auto &p : px) { s = s * 1664525u + 1013904223u; p = s; }
    blob = std::make_shared<const std::vector<uint8_t>>(screenshot::encodePng(px, 256, 256));
    REQUIRE(blob->size() > 128 * 1024);

    // Same installation the Super+F7 release performs (Server.cc:1102-1103).
    ClipboardImage *ci = ClipboardImage::create(server.display, blob);
    wlr_seat_set_selection(server.seat, &ci->base, wl_display_next_serial(server.display));

    // The client's wl_data_offer.receive("image/png", fd) lands here.
    int fds[2]; REQUIRE(pipe(fds) == 0);
    rfd = fds[0]; wfd = fds[1];
    wlr_data_source *src = server.seatSelectionSourceForTest();
    REQUIRE(src == &ci->base);
    src->impl->send(src, "image/png", wfd);

    // Client never reads: pump until the pipe is full and the Writer parks.
    for (int i = 0; i < 50; ++i) server.dispatch();
    REQUIRE(fcntl(wfd, F_GETFD) != -1);      // in flight, not finished/errored
    REQUIRE(blob.use_count() == 3);          // test + ClipboardImage + Writer
  } // ~Server: listener disconnects, destroy_clients, wl_display_destroy.

  // THE BUG — both fail today: ~Server has no Writer registry and
  // wl_event_loop_destroy does not free surviving fd sources/user data.
  CHECK(fcntl(wfd, F_GETFD) == -1);   // currently != -1: Writer's fd leaked
  CHECK(blob.use_count() == 1);       // currently 2: Writer's blob ref leaked
  if (fcntl(wfd, F_GETFD) != -1) close(wfd);
  close(rfd);
  // Under ASAN/LSAN the Writer struct + wl_event_source also report as
  // definite leaks; fd + use_count make it visible without sanitizers.
  // Optional fully-injected variant (racy-window shape): Super+F7 drag via
  // injectKey/injectPointer*ForTest as in screenshot_e2e_test.cc:67-71, then
  // impl->send and scope-exit the Server with NO intervening dispatch — the
  // Writer leaks at offset 0 even for a tiny PNG.

